// Arma el prompt del Agente Info: le inyecta TODA la tabla bot.info_negocio
// (via Datos Info) + la pregunta. El agente redacta SOLO con estos datos.
const d = $('Leer Intención').first().json;
let filas = [];
try {
  filas = $('Datos Info').all().map((i) => i.json).filter((r) => r && r.clave && r.valor);
} catch (e) { filas = []; }
const tabla = filas.map((r) => '- ' + r.clave + ': ' + String(r.valor).trim()).join('\n');
return [{ json: {
  ...d,
  infoFilas: filas.length,
  // encargar (2026-08-06): misma maquinaria de info, pero el marco es "el cliente
  // quiere encargar -> decile como se toma el pedido con los datos reales". El
  // Agente Info redacta natural (no hardcodeado) y escala si no hay datos.
  promptInfo: (d.intencion === 'encargar'
    ? [
      'DATOS DEL NEGOCIO (unica fuente; no inventes mail/direccion/horarios):',
      tabla || '(sin datos)',
      '',
      'EL CLIENTE CONFIRMA QUE QUIERE ENCARGAR. No hay nada que cotizar en este turno.',
      'Con los datos de arriba, decile natural y breve como se toma el pedido (por mail o',
      'en el local). No listes horarios de mas ni repitas datos que no pidio.',
      '',
      'MENSAJE DEL CLIENTE:',
      String(d.userMessage || ''),
    ]
    : [
      'DATOS DEL NEGOCIO (unica fuente de verdad; no afirmes nada que no este aca):',
      tabla || '(sin datos)',
      '',
      'PREGUNTA DEL CLIENTE:',
      String(d.userMessage || ''),
    ]).join('\n'),
} }];
